// Hand-written `@nestjs/axios` stub. The same one the other fixtures use, with
// the verbs this one needs: a request that is not a GET or a POST is exactly
// what nothing else here writes down.

export interface AxiosResponse<Data = unknown> {
  data: Data;
  status: number;
}

