  put<Data = unknown>(url: string, body?: unknown, config?: unknown): { data: AxiosResponse<Data> };
  patch<Data = unknown>(url: string, body?: unknown, config?: unknown): { data: AxiosResponse<Data> };
  delete<Data = unknown>(url: string, config?: unknown): { data: AxiosResponse<Data> };
